def nearest_color(g, metric='manhattan', ties=None):
    H,W=len(g),len(g[0])
    S=[(r,c,g[r][c]) for r in range(H) for c in range(W) if g[r][c]!=0 and g[r][c]!=8]
    out=[row[:] for row in g]
    def dist(sr,sc,sr2,sc2):
        if metric=='manhattan': return abs(sr-sr2)+abs(sc-sc2)
        if metric=='euclid': return max(abs(sr-sr2),abs(sc-sc2))  # chebyshev
        return -1
    res={'manhattan':None,'chebyshev':None}
    for metric in ['manhattan','chebyshev']:
        grid={}
        for r in range(H):
            for c in range(W):
                if g[r][c]==8:
                    ds=[d for sr,sc,v in S for d in [dist(sr,sc,r,c)]]
                    mind=min(ds)
                    bestv=[v for sr,sc,v in S if dist(sr,sc,r,c)==mind]
                    if ties is None: bestv.sort()
                    grid[(r,c)]=(mind,bestv)
        ok=True
        for (r,c),(m,bv) in grid.items():
            if len(bv)!=1 or bv[0]!=go[r][c]: ok=False
        res[metric]=ok
    return res
